    "guideSecScreenRecordingContent": "画面の任意の領域を指定して、MP4、WebM、またはアニメーションGIFとして録画できます。GIF録画では1:1のネイティブ解像度、1080p、720p、480pの画質プロファイルに対応し、録画中にファイル容量のリアルタイム見積もりを表示します。ブラウザの安定した動作を確保するため、GIF録画の最大許容時間は1分間（60秒）です。",
