      "guideSecScreenRecording": "Gravação de tela (Vídeo e GIF)",
      "guideSecScreenRecordingContent": "Grave qualquer região da tela como vídeo MP4, WebM ou GIF animado. As gravações em GIF oferecem resolução nativa 1:1, perfis em 1080p, 720p e 480p, além de cálculo em tempo real do tamanho estimado do arquivo. O tempo máximo de gravação em GIF é de 1 minuto (60 s) para máxima estabilidade do navegador.",
