      "guideSecScreenRecording": "Registrazione dello schermo (Video e GIF)",
      "guideSecScreenRecordingContent": "Registra qualsiasi porzione dello schermo in formato MP4, WebM o GIF animata. Le registrazioni GIF supportano la risoluzione nativa 1:1, profili a 1080p, 720p e 480p, con stima in tempo reale della dimensione del file. La durata massima di registrazione per le GIF è di 1 minuto (60 s) per garantire prestazioni ottimali del browser.",
